#!/usr/bin/env python3
"""Plot only aggregate estimates generated by the v50 raw-data refit."""
import argparse
import json
from pathlib import Path

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt


def draw_panel(ax, entries, title, contrast, xmax):
    ax.axvline(1, color='#98a0a8', ls='--', lw=1.2, zorder=0)
    for y, (label, record, color) in zip([1, 0], entries):
        b = record['b_or_contrast']
        lo, hi = record['paired_percentile_95']
        ax.errorbar(b, y, xerr=[[b-lo], [hi-b]], fmt='o', color=color,
                    ms=8, capsize=5, lw=2.2, zorder=3)
        ax.text(1.04, y, f'{b:.2f}  [{lo:.2f}, {hi:.2f}]',
                transform=ax.get_yaxis_transform(), va='center', ha='left',
                fontsize=10, color='#343c45')
    ax.set_yticks([1, 0], [x[0] for x in entries])
    ax.set_xlim(-0.30, xmax)
    ax.set_ylim(-0.65, 1.65)
    ax.set_title(title, loc='left', pad=14, fontweight='bold', fontsize=12)
    ax.set_xlabel('Power exponent b (b = 1: proportional response)', labelpad=8)
    ax.text(0, -0.47, contrast, transform=ax.transAxes, fontsize=11,
            fontweight='bold', color='#222a34')
    ax.grid(axis='x', color='#e8ebef', lw=0.8)
    ax.set_axisbelow(True)
    for side in ['top', 'right', 'left']:
        ax.spines[side].set_visible(False)
    ax.spines['bottom'].set_color('#bbc2cb')
    ax.tick_params(axis='y', length=0, pad=9)


def main(source, output):
    data = json.loads(source.read_text())
    main = data['primary_n89']['results']
    secondary = data['outcome_sensitivity_shared_n59']['results']
    plt.rcParams.update({'font.family':'DejaVu Sans', 'font.size':10,
                         'svg.fonttype':'none', 'svg.hashsalt':'onishibari-v50'})
    fig, axes = plt.subplots(2, 1, figsize=(11, 8.1))
    fig.subplots_adjust(left=.29, right=.76, top=.83, bottom=.27, hspace=1.35)
    fig.suptitle('Pulsatilla alpina: the offspring endpoint changes the gain curve',
                 x=.04, ha='left', y=.975, fontsize=16, fontweight='bold')
    fig.text(.04, .925, 'Secondary analysis of public individual data | one population, 2022',
             color='#586472', fontsize=11)
    def contrast_text(label, record):
        lo, hi = record['paired_percentile_95']
        return f"{label}: {record['b_or_contrast']:.2f}  [{lo:.2f}, {hi:.2f}]"
    draw_panel(axes[0], [
        ('Female: pistil count', main['female_discounted'], '#7057a3'),
        ('Male: stamen count', main['male_discounted'], '#bf7035'),
    ], 'A. Same 89 plants; both outcomes discount selfed offspring',
        contrast_text('Female minus male', main['female_minus_male_discounted']), 2.0)
    draw_panel(axes[1], [
        ('Mature seeds\nEqual seed weights', secondary['female_mature'], '#697884'),
        ('Discounted female success\nSelfed seeds weighted 0.05', secondary['female_discounted'], '#007f80'),
    ], 'B. Female response in the same 59 single-flowered controls',
        contrast_text('Discounted minus mature-seed exponent',
                      secondary['female_discounted_minus_mature']), 4.9)
    fig.text(.04, .065,
             'Bars: 95% percentile intervals from 10,000 paired plant resamples. '
             'Allocation uses organ counts, not individual floral mass.\n'
             'Intervals condition on the deposited paternity estimates and fixed inbreeding depression '
             '(delta = 0.95). No survival was measured here.\n'
             'Panel B is an overlapping subset of panel A, not an independent population. '
             'Positive pistil counts: 70 in A; 44 in B.',
             fontsize=9, color='#586472', linespacing=1.6)
    output.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(output.with_suffix('.svg'), metadata={'Date':None}, facecolor='white')
    fig.savefig(output.with_suffix('.png'), dpi=160, facecolor='white')
    plt.close(fig)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path,
                        default=Path('data/2026-11-21_pulsatilla_paired_gain_refit_v50.json'))
    parser.add_argument('--output', type=Path,
                        default=Path('figures/2026-11-21_pulsatilla_gain_curves_v50'))
    args = parser.parse_args()
    main(args.source, args.output)
